using Astronomy.MediaFactory.Core.KnowledgeFoundation.Integration; using Microsoft.Extensions.DependencyInjection;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Integration;
public sealed class AstronomyKnowledgeFoundationCapabilitiesTests{[Fact]public void Snapshot_lookup_and_sections_are_stable(){var d=new AstronomyKnowledgeFoundationCapabilityDescriptor(new(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"catalog.metadata"),"catalog.metadata","Catalog","Catalog",0,typeof(IDisposable),typeof(System.IO.MemoryStream),ServiceLifetime.Singleton);var c=new AstronomyKnowledgeFoundationCapabilities(new([d]));Assert.Same(c.Snapshot,c.Snapshot);Assert.True(c.TryGet(d.Id,out var got));Assert.Same(d,got);Assert.False(c.TryGet(new(AstronomyKnowledgeFoundationCapabilityKind.Catalog,"missing"),out _));Assert.Same(c.Snapshot.Catalog,c.GetByKind(AstronomyKnowledgeFoundationCapabilityKind.Catalog));Assert.Throws<ArgumentOutOfRangeException>(()=>c.GetByKind((AstronomyKnowledgeFoundationCapabilityKind)99));Assert.DoesNotContain(typeof(IAstronomyKnowledgeFoundationCapabilities).GetMethods(),m=>m.Name.Contains("Service",StringComparison.Ordinal));}}
